const j = pm.response.json();
pm.test("has token", () => { pm.expect(j).to.have.property("access_token"); });
pm.environment.set("access_token", j.access_token);
pm.environment.set("token_expiry", Date.now() + j.expires_in * 1000);
pm.collectionVariables.set("refresh_token", j.refresh_token);
pm.test("expiry in future", () => pm.expect(pm.environment.get("token_expiry")).to.be.above(Date.now()));

const expiry = Number(pm.environment.get("token_expiry") || 0);
if (!pm.environment.get("access_token") || expiry < Date.now()) {
  pm.sendRequest({
    url: pm.environment.get("auth_url") + "/token",
    method: "POST",
    header: { "Content-Type": "application/x-www-form-urlencoded" },
    body: { mode: "urlencoded", urlencoded: [{ key: "grant_type", value: "refresh_token" }, { key: "refresh_token", value: pm.environment.get("refresh_token") }] }
  }, function (err, res) {
    if (err) { throw err; }
    pm.environment.set("access_token", res.json().access_token);
  });
}
pm.request.headers.upsert({ key: "Authorization", value: "Bearer " + "{{access_token}}" });

const secret = pm.environment.get("api_secret");
const body = pm.request.body.raw;
const sig = CryptoJS.HmacSHA256(body, secret);
pm.request.headers.upsert({ key: "X-Signature", value: sig.toString(CryptoJS.enc.Hex) });
pm.request.headers.upsert({ key: "X-Signature-B64", value: CryptoJS.enc.Base64.stringify(sig) });
pm.environment.set("sig_len", sig.toString().length);

const crypto = require('crypto');
const h = crypto.createHmac('sha256', 'secret').update('message').digest('hex');
pm.test("hmac matches", () => pm.expect(h).to.equal("8b5f48702995c1598c573db1e21866a9b825d4a794d169d7060a03605796360b"));
pm.test("sha1", () => pm.expect(crypto.createHash('sha1').update('hello').digest('hex')).to.equal("aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d"));
pm.test("md5 b64", () => pm.expect(crypto.createHash('md5').update('hello').digest('base64')).to.equal("XUFAKrxLKna5cZ2REBfFkg=="));
pm.test("randomBytes", () => pm.expect(crypto.randomBytes(8).length).to.equal(8));

const html = pm.response.text();
const m = html.match(/name="csrf_token"\s+value="([^"]+)"/);
pm.test("csrf found", () => { pm.expect(m).to.not.be.null; });
pm.collectionVariables.set("csrf", m[1]);
const meta = /<meta name="csrf" content="([^"]+)"/.exec(html);
pm.environment.set("csrf_meta", meta ? meta[1] : "none");
pm.test("cookie header", () => pm.response.to.have.header("Set-Cookie"));

const key = CryptoJS.enc.Hex.parse("000102030405060708090a0b0c0d0e0f");
const iv = CryptoJS.enc.Hex.parse("0f0e0d0c0b0a09080706050403020100");
const enc = CryptoJS.AES.encrypt("hello world 123", key, { iv: iv, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7 });
pm.environment.set("ct", enc.toString());
pm.request.body.update(JSON.stringify({ data: enc.toString() }));
pm.environment.set("ct_hex", enc.ciphertext.toString(CryptoJS.enc.Hex));
const dec = CryptoJS.AES.decrypt(enc, key, { iv: iv });
pm.environment.set("pt", dec.toString(CryptoJS.enc.Utf8));

const key = CryptoJS.enc.Hex.parse("000102030405060708090a0b0c0d0e0f");
const enc = CryptoJS.AES.encrypt("hello world 123", key, { mode: CryptoJS.mode.ECB });
pm.environment.set("ct", enc.toString());
pm.environment.set("pt", CryptoJS.AES.decrypt(enc.toString(), key, { mode: CryptoJS.mode.ECB }).toString(CryptoJS.enc.Utf8));

const key = CryptoJS.enc.Hex.parse("000102030405060708090a0b0c0d0e0f");
const iv = CryptoJS.enc.Hex.parse("0f0e0d0c0b0a09080706050403020100");
const enc = CryptoJS.AES.encrypt("hello world 123", key, { iv: iv, mode: CryptoJS.mode.CTR, padding: CryptoJS.pad.NoPadding });
pm.environment.set("ct_hex", enc.ciphertext.toString());

const enc = CryptoJS.AES.encrypt("top secret payload", "pw").toString();
pm.test("roundtrip", () => pm.expect(CryptoJS.AES.decrypt(enc, "pw").toString(CryptoJS.enc.Utf8)).to.equal("top secret payload"));
pm.test("openssl salted", () => pm.expect(enc.slice(0, 10)).to.equal("U2FsdGVkX1"));
pm.test("decrypt openssl output", () => pm.expect(CryptoJS.AES.decrypt("U2FsdGVkX18BAgMEBQYHCEU24AP+2u3zMJEzVzvUI84=", "pw").toString(CryptoJS.enc.Utf8)).to.equal("hello"));

pm.test("md5", () => pm.expect(CryptoJS.MD5("hello").toString()).to.equal("5d41402abc4b2a76b9719d911017c592"));
pm.test("sha256", () => pm.expect(CryptoJS.SHA256("abc").toString()).to.equal("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"));
pm.test("b64", () => pm.expect(CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse("hello"))).to.equal("aGVsbG8="));
pm.test("b64 parse", () => pm.expect(CryptoJS.enc.Base64.parse("aGVsbG8=").toString(CryptoJS.enc.Utf8)).to.equal("hello"));
pm.test("pbkdf2", () => pm.expect(CryptoJS.PBKDF2("password", "salt", { keySize: 4, iterations: 2 }).toString()).to.equal("ea6c014dc72d6f8ccd1ed92ace1d41f0"));
pm.test("wordarray", () => pm.expect(CryptoJS.lib.WordArray.random(16).sigBytes).to.equal(16));
pm.test("utf8 multibyte", () => pm.expect(CryptoJS.enc.Hex.stringify(CryptoJS.enc.Utf8.parse("é"))).to.equal("c3a9"));

pm.environment.set("order_id", pm.response.json().id);
pm.execution.setNextRequest("Get Order");
pm.test("created", () => pm.response.to.have.status(201));

