const o = { a: 1, b: { c: [1, 2, 3] }, s: "hello world", n: null, t: true, e: [] };
pm.test("equal", () => { pm.expect(o.a).to.equal(1); pm.expect(o.a).to.eql(1); pm.expect(o.a).to.not.equal(2); });
pm.test("deep", () => { pm.expect(o.b).to.eql({ c: [1, 2, 3] }); pm.expect(o.b).to.deep.equal({ c: [1, 2, 3] }); pm.expect(o.b).to.not.equal({ c: [1, 2, 3] }); });
pm.test("include", () => { pm.expect(o.s).to.include("world"); pm.expect(o.s).to.contain("hello"); pm.expect([1, 2, 3]).to.include(2); pm.expect(o.b.c).to.include.members([1, 3]); pm.expect({ a: 1, b: 2 }).to.include({ a: 1 }); });
pm.test("property", () => { pm.expect(o).to.have.property("a"); pm.expect(o).to.have.property("a", 1); pm.expect(o).to.have.own.property("b"); pm.expect(o).to.have.nested.property("b.c[1]", 2); pm.expect(o).to.not.have.property("zzz"); });
pm.test("types", () => { pm.expect(o.s).to.be.a("string"); pm.expect(o.b.c).to.be.an("array"); pm.expect(o.n).to.be.null; pm.expect(o.t).to.be.true; pm.expect(o.b).to.be.an("object"); pm.expect(undefined).to.be.undefined; pm.expect(1).to.be.a("number"); });
pm.test("numeric", () => { pm.expect(5).to.be.above(3); pm.expect(5).to.be.below(9); pm.expect(5).to.be.at.least(5); pm.expect(5).to.be.at.most(5); pm.expect(5).to.be.within(1, 10); pm.expect(5.1).to.be.closeTo(5, 0.2); });
pm.test("length", () => { pm.expect(o.b.c).to.have.lengthOf(3); pm.expect(o.b.c).to.have.length(3); pm.expect(o.b.c).to.have.length.above(2); pm.expect(o.s).to.have.length.within(5, 20); pm.expect(o.e).to.be.empty; pm.expect("").to.be.empty; pm.expect({}).to.be.empty; });
pm.test("oneOf match", () => { pm.expect(200).to.be.oneOf([200, 201]); pm.expect("abc123").to.match(/^[a-z]+\d+$/); pm.expect("x").to.exist; pm.expect(1).to.be.ok; pm.expect(0).to.not.be.ok; pm.expect(false).to.be.false; });
pm.test("keys", () => { pm.expect({ a: 1, b: 2 }).to.have.all.keys("a", "b"); pm.expect({ a: 1, b: 2 }).to.have.any.keys("a", "z"); pm.expect({ a: 1, b: 2 }).to.contain.keys("a"); pm.expect({ a: 1, b: 2 }).to.have.keys(["a", "b"]); });
pm.test("and chain", () => { pm.expect(o.s).to.be.a("string").and.include("hello").and.have.lengthOf(11); });
pm.test("throws", () => { pm.expect(() => { throw new Error("boom"); }).to.throw(); pm.expect(() => { throw new TypeError("bad"); }).to.throw(TypeError, "bad"); pm.expect(() => 1).to.not.throw(); });
pm.test("members satisfy", () => { pm.expect([1, 2, 3]).to.have.members([3, 2, 1]); pm.expect(4).to.satisfy((n) => n % 2 === 0); pm.expect(NaN).to.be.NaN; });
pm.test("instanceof", () => { pm.expect([]).to.be.instanceOf(Array); pm.expect(new Error("x")).to.be.an.instanceof(Error); });

pm.test("status", () => { pm.response.to.have.status(200); pm.response.to.have.status("OK"); pm.response.to.be.ok; pm.response.to.be.success; pm.response.to.not.be.error; pm.response.to.not.be.serverError; });
pm.test("header", () => { pm.response.to.have.header("Content-Type"); pm.response.to.have.header("x-request-id", "abc"); pm.response.to.not.have.header("X-Nope"); });
pm.test("body", () => { pm.response.to.be.json; pm.response.to.have.jsonBody("a.b", 2); pm.response.to.have.jsonBody("list[1]", "y"); pm.response.to.have.body("\"a\""); pm.response.to.be.withBody; });
pm.test("expect(pm.response)", () => { pm.expect(pm.response).to.have.status(200); pm.expect(pm.response).to.be.ok; });
pm.test("fields", () => { pm.expect(pm.response.code).to.equal(200); pm.expect(pm.response.status).to.equal("OK"); pm.expect(pm.response.responseTime).to.be.below(100); pm.expect(pm.response.responseSize).to.be.above(5); pm.expect(pm.response.size().body).to.be.above(5); pm.expect(pm.response.headers.get("content-type")).to.include("json"); });

